<?php
session_start();
require_once __DIR__ . '/admin_auth_guard.php';
$activeAdminAccount = adminRequireActiveAccount($conn ?? null);
if(($_SESSION['role']??'')!=='admin'||empty($_SESSION['id'])){header('Location: ../login_form.php');exit;}
require_once __DIR__.'/../dbcon.php';require_once __DIR__.'/../approval_workflow.php';$conn=dbcon();$adminId=(int)$_SESSION['id'];
$user=wfRow($conn,'SELECT * FROM user WHERE user_id = ?','i',[$adminId]);if(!$user){http_response_code(403);exit('Access denied.');}
$borrowId=filter_var($_GET['id']??'',FILTER_VALIDATE_INT);if(!$borrowId){http_response_code(404);exit('Request not found.');}
$_SESSION['workflow_csrf']??=bin2hex(random_bytes(32));$error='';$notice=$_SESSION['workflow_notice']??'';unset($_SESSION['workflow_notice']);
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{if(!hash_equals($_SESSION['workflow_csrf'],(string)($_POST['csrf']??'')))throw new InvalidArgumentException('Your session expired. Refresh and try again.');$_SESSION['workflow_notice']=wfAdminAction($conn,$borrowId,$adminId,(string)($_POST['action']??''),$_POST);header('Location: release.php?id='.$borrowId);exit;}
 catch(InvalidArgumentException $e){$error=$e->getMessage();}catch(Throwable $e){error_log('JTM workflow: '.$e->getMessage());$error='Unable to process the request. Please try again later.';}
}
try{$snapshot=wfSnapshot($conn,$borrowId);}catch(InvalidArgumentException $e){http_response_code(404);exit(approverEscape($e->getMessage()));}
$b=wfRow($conn,'SELECT * FROM borrowing WHERE borrow_id = ?','i',[$borrowId]);$last=wfLatest($conn,$borrowId);$d=wfDepartment($conn,$snapshot['unit_bahagian']);
$items=wfAll($conn,'SELECT bi.*,i.item_name FROM borrowing_item bi LEFT JOIN item i ON i.item_tag=bi.item_tag WHERE bi.borrow_id = ? ORDER BY bi.borrow_item_id','s',[(string)$borrowId]);
$available=wfAll($conn,"SELECT item_tag,item_name,item_category FROM item WHERE item_status='Available' ORDER BY item_category,item_name");
$choices=wfApproverChoices($conn);$suggestedId=(int)($d['department_id']??0);$suggestedReady=$d&&$d['is_active']&&trim($d['lead_name'])!==''&&!empty($d['approval_email']);$chosenId=(int)($_POST['approver_department_id']??($suggestedReady?$suggestedId:0));
$locked=($last&&$last['handed_over_at'])||(!$last&&$b['status']!=='Baru');$current_page='borrow';
?>
