<section class="panel"><h2><?=approverEscape($snapshot['nama'])?></h2><p class="muted"><?=approverEscape($snapshot['no_id_staf'].' · '.$snapshot['unit_bahagian'])?></p><p><strong>Purpose:</strong> <?=approverEscape($snapshot['tujuan_tempahan'])?><br><strong>Location:</strong> <?=approverEscape($snapshot['lokasi_penggunaan'])?><br><strong>Period:</strong> <?=approverEscape($snapshot['start_date'].' → '.$snapshot['end_date'])?></p><p class="muted small">Department lead: <?= $d&&$d['is_active']?approverEscape($d['lead_name'].' · '.$d['approval_email']):'No active lead configured — update Department Approvers or the applicant department.'?></p></section>
<?php if(!$locked):?><section class="panel"><p class="section-kicker">Step 1 · Equipment</p><h2>Select and reserve inventory</h2><p class="muted small">Items are reserved until approval and handover. Changing the selection requires fresh approval.</p><form method="post"><input type="hidden" name="csrf" value="<?=approverEscape($_SESSION['workflow_csrf'])?>"><input type="hidden" name="action" value="add"><label for="tagno">Available asset</label><div class="select-wrap"><select id="tagno" name="tagno" required><option value="">Select an available asset</option><?php foreach($available as $i):?><option value="<?=approverEscape($i['item_tag'])?>"><?=approverEscape($i['item_category'].' / '.$i['item_tag'].' / '.$i['item_name'])?></option><?php endforeach;?></select></div><button class="btn btn-primary" type="submit"><i class="fa-solid fa-bookmark"></i> Reserve Item</button></form></section><?php endif;?>
<section class="panel"><p class="section-kicker">Step 1 · Reserved items</p><h2>Selected equipment</h2><table><thead><tr><th>Asset tag</th><th>Item</th><th>Serial</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><?=approverEscape($i['item_tag'])?></td><td><?=approverEscape($i['item_name'])?></td><td><?=approverEscape($i['item_siri'])?></td><td><?=approverEscape($i['status'])?></td><td><?php if(!$locked):?><form method="post"><input type="hidden" name="csrf" value="<?=approverEscape($_SESSION['workflow_csrf'])?>"><input type="hidden" name="action" value="remove"><input type="hidden" name="item_id" value="<?=(int)$i['borrow_item_id']?>"><button class="btn btn-secondary btn-small" onclick="return confirm('Remove this item? Any existing approval will be invalidated.')"><i class="fa-solid fa-xmark"></i> Remove</button></form><?php endif;?></td></tr><?php endforeach;?><?php if(!$items):?><tr><td colspan="5" class="muted">No inventory items selected.</td></tr><?php endif;?></tbody></table></section>
<?php if($last):?><section class="panel"><h2>Assigned approval</h2><p><strong><?=approverEscape($last['state']==='pending'?'Waiting for approval — '.$last['lead_name']:ucfirst($last['state']))?></strong> · Round <?=(int)$last['round_no']?></p><p class="muted">Approver: <?=approverEscape($last['lead_name'])?><br>JTM confirmed: <?=approverEscape($last['confirmed_name'].' / '.$last['confirmed_at'])?><?php if($last['decision_at']):?><br>Decision: <?=approverEscape($last['decision_at'])?><?php endif;?><?php if($last['decision_note']):?><br>Remarks: <?=approverEscape($last['decision_note'])?><?php endif;?><?php if($last['handed_over_at']):?><br>Handed over: <?=approverEscape($last['handed_over_at'])?><?php endif;?></p><?php if($last['state']==='approved'&&$last['pdf_filename']):?><a class="button" href="../approval_pdf.php?id=<?=$borrowId?>" target="_blank" rel="noopener">View Signed PDF</a><?php endif;?></section><?php endif;?>
<?php if(!$locked):?><section class="panel"><form method="post"><input type="hidden" name="csrf" value="<?=approverEscape($_SESSION['workflow_csrf'])?>"><?php if(!$last||in_array($last['state'],['rejected','superseded'],true)):?>
<p class="section-kicker">Step 2 · Approval</p><h2>Assign an approver</h2><p class="muted small">Applicant’s department: <?=approverEscape($snapshot['unit_bahagian'])?><br>Suggested approver: <?=approverEscape($suggestedReady?$d['lead_name'].' · '.$d['department_name']:'No active department lead configured — choose another approver or complete the setup')?></p>
<label for="assign-to">Choose one approver</label><div class="select-wrap"><select id="assign-to" name="approver_department_id"><option value="">Select an approver</option>
