<div id="approver-preview" style="background:#f4f7fd;border:1px solid #dce3ee;border-radius:14px;padding:18px;margin:16px 0" aria-live="polite"><strong id="preview-name"></strong><p id="preview-position"></p><p id="preview-department"></p><p id="preview-email"></p><p id="preview-ready" class="small"></p><span id="preview-suggested" class="pill" hidden>Suggested based on applicant’s department</span></div>
<div id="assignment-reason-box" class="field-group"><label for="assignment-reason">Reason for choosing a different approver</label><p class="workflow-help">Required only when the selected approver differs from the suggested approver.</p><textarea id="assignment-reason" name="assignment_reason" maxlength="300" rows="2" placeholder="Example: Applicant is working under this department for the event."><?=approverEscape($_POST['assignment_reason']??'')?></textarea><p class="field-tip"><i class="fa-solid fa-pen"></i> Explain the override clearly for the audit trail.</p></div>
<?php endif;?>
