<?php if(!$last||in_array($last['state'],['rejected','superseded'],true)):?><button class="btn btn-primary" id="send-approval" name="action" value="submit" <?=!$items?'disabled':''?>><i class="fa-solid fa-paper-plane"></i> Confirm &amp; Send for Approval</button><?php endif;?>
<?php if($last&&$last['state']==='pending'):?><p class="muted">Waiting for approval — <?=approverEscape($last['lead_name'])?>. No equipment handover yet.</p><?php endif;?>
