</div></form></section><?php endif;?>
<?php if($last): $events=wfAll($conn,'SELECT * FROM borrowing_approval_events WHERE approval_id=? ORDER BY event_id','i',[(int)$last['approval_id']]); ?><section class="panel"><h2>Approval audit trail</h2><table><thead><tr><th>Time</th><th>Action</th><th>By</th><th>Remarks</th></tr></thead><tbody><?php foreach($events as $event):?><tr><td><?=approverEscape($event['occurred_at'])?></td><td><?=approverEscape(str_replace('_',' ',$event['action']))?></td><td><?=approverEscape($event['actor_role'])?></td><td><?=approverEscape($event['detail'])?></td></tr><?php endforeach;?></tbody></table></section><?php endif;?>
</main></div><script>
const choices=<?=json_encode(array_map(fn($c)=>['id'=>(int)$c['department_id'],'name'=>$c['lead_name'],'position'=>wfApproverPosition($c),'department'=>$c['department_name'],'email'=>$c['approval_email'],'active'=>(bool)$c['is_active'],'accountReady'=>(bool)$c['account_ready'],'imageReady'=>(bool)$c['image_ready']],$choices),JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>;
const suggestedId=<?=$suggestedId?>, hasItems=<?= $items?'true':'false'?>;
const select=document.getElementById('assign-to');
function updateApprover(){
 const person=choices.find(p=>p.id===Number(select.value));
 document.getElementById('preview-name').textContent=person?.name||'Choose an approver';
 document.getElementById('preview-position').textContent=person?.position||'';
 document.getElementById('preview-department').textContent=person?.department||'';
 document.getElementById('preview-email').textContent=person?.email||'';
 document.getElementById('preview-ready').textContent=person?('Account: '+(person.accountReady?'Activated':'Setup required')+' · Signature & chop: '+(person.imageReady?'Ready':'Not uploaded')):'';
 document.getElementById('preview-suggested').hidden=!person||person.id!==suggestedId;
 const override=!!person&&person.id!==suggestedId;
 const reasonBox=document.getElementById('assignment-reason-box');
 const wasHidden=reasonBox.hidden;
 reasonBox.hidden=!override;
 const reason=document.getElementById('assignment-reason');reason.required=override;
 if(override&&wasHidden)setTimeout(()=>reason.focus(),80);
 document.getElementById('send-approval').disabled=!hasItems||!person||!person.active||!person.accountReady;
}
if(select){select.addEventListener('change',updateApprover);updateApprover();}
</script></body></html>
